/* ── 로마자 변환 (국어의 로마자 표기법) ───────────────────── */
const _CHO = ['g','kk','n','d','tt','r','m','b','pp','s','ss','','j','jj','ch','k','t','p','h'];
const _JUNG = ['a','ae','ya','yae','eo','e','yeo','ye','o','wa','wae','oe','yo','u','wo','we','wi','yu','eu','ui','i'];
const _JONG = ['','k','k','k','n','n','n','t','l','k','m','p','l','l','p','l','m','p','p','t','t','ng','t','t','k','t','p','t'];
const _SPLIT = {3:['k',9],5:['n',12],6:['n',18],9:['l',0],10:['l',6],11:['l',7],12:['l',9],13:['l',16],14:['l',17],15:['l',18],18:['p',9]};
const _LINK = {1:0,2:1,4:2,7:3,8:5,16:6,17:7,19:9,20:10,21:11,22:12,23:14,24:15,25:16,26:17,27:18};
const _SUF = {'동':'dong','읍':'eup','면':'myeon','가':'ga','구':'gu','시':'si','군':'gun','도':'do'};

function _rom(word) {
  const sy = [];
  for (const ch of word) {
    const c = ch.charCodeAt(0) - 0xAC00;
    sy.push(c < 0 || c > 11171 ? null : [Math.floor(c / 588), Math.floor((c % 588) / 28), c % 28]);
  }
  const n = sy.length, fin = new Array(n).fill(''), ini = sy.map(s => s ? s[0] : null), ovr = new Array(n).fill(null);
  for (let i = 0; i < n; i++) {
    const s = sy[i]; if (!s) continue;
    const j = s[2], nx = sy[i + 1]; if (!j) continue;
    if (nx && ini[i + 1] === 11) {
      if (_SPLIT[j]) { fin[i] = _SPLIT[j][0]; ini[i + 1] = _SPLIT[j][1]; }
      else if (j === 21) fin[i] = 'ng';
      else { fin[i] = ''; ini[i + 1] = _LINK[j]; }
      continue;
    }
    let rep = _JONG[j];
    if (nx) {
      let ni = ini[i + 1];
      if (rep === 'l' && ni === 2) { ni = 5; ovr[i + 1] = 'l'; }
      else if (rep === 'n' && ni === 5) { rep = 'l'; ovr[i + 1] = 'l'; }
      else if ((rep === 'm' || rep === 'ng') && ni === 5) ni = 2;
      else if ((rep === 'k' || rep === 'p') && ni === 5) { ni = 2; rep = rep === 'k' ? 'ng' : 'm'; }
      else if (rep === 'k' && (ni === 2 || ni === 6)) rep = 'ng';
      else if (rep === 't' && (ni === 2 || ni === 6)) rep = 'n';
      else if (rep === 'p' && (ni === 2 || ni === 6)) rep = 'm';
      ini[i + 1] = ni;
    }
    fin[i] = rep;
  }
  let out = '';
  for (let i = 0; i < n; i++) { const s = sy[i]; if (!s) continue; out += (ovr[i] || _CHO[ini[i]]) + _JUNG[s[1]] + fin[i]; }
  return out;
}

function _plain(name) {
  let out = '';
  for (const tok of name.match(/[\uac00-\ud7a3]+|[0-9]+|[^\uac00-\ud7a30-9]+/g) || []) {
    if (/^[\uac00-\ud7a3]+$/.test(tok)) out += _rom(tok).toLowerCase();
    else if (/^[0-9]+$/.test(tok)) out += tok;
    else out += '-';
  }
  return out.replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '');
}

function toSlug(name) {
  name = String(name || '').trim();
  const last = name.slice(-1);
  if (name.length > 1 && _SUF[last]) {
    const base = _plain(name.slice(0, -1));
    if (base) return base + '-' + _SUF[last];
  }
  return _plain(name);
}

/* ── 지역 조회 ──────────────────────────────────────────── */
const SIDO_BY = Object.fromEntries(SIDO.map(s => [s[0], { s: s[0], ko: s[1], short: s[2] }]));

function gugunList(sidoSlug) {
  return (GUGUN[sidoSlug] || []).map(v => { const i = v.indexOf('|'); return { s: v.slice(0, i), ko: v.slice(i + 1) }; });
}
function findGugun(sidoSlug, gugunSlug) {
  return gugunList(sidoSlug).find(g => g.s === gugunSlug) || null;
}
function dongList(sidoSlug, gugunSlug) {
  const raw = DONG[sidoSlug + '/' + gugunSlug];
  if (!raw) return [];
  return raw.split(',').map(ko => ({ s: toSlug(ko), ko }));
}
function findDong(sidoSlug, gugunSlug, dongSlug) {
  return dongList(sidoSlug, gugunSlug).find(d => d.s === dongSlug) || null;
}
function gugunCount() { let n = 0; for (const k in GUGUN) n += GUGUN[k].length; return n; }
function dongCount() { let n = 0; for (const k in DONG) n += DONG[k].split(',').length; return n; }

/* ── 유틸 ───────────────────────────────────────────────── */
function esc(s) {
  return String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;')
    .replace(/>/g, '&gt;').replace(/"/g, '&quot;').replace(/'/g, '&#39;');
}
function hash(str) {
  let h = 2166136261;
  for (let i = 0; i < str.length; i++) { h ^= str.charCodeAt(i); h = Math.imul(h, 16777619); }
  return (h >>> 0);
}
function pick(arr, seed) { return arr[hash(seed) % arr.length]; }
function pickN(arr, seed, n) {
  const len = Math.min(n, arr.length);
  if (len <= 0) return [];
  const out = [], used = new Set();
  let h = hash(seed);
  while (out.length < len) {
    let i = h % arr.length;
    while (used.has(i)) i = (i + 1) % arr.length;   /* 충돌 시 선형 탐사 — 반드시 종료 */
    used.add(i); out.push(arr[i]);
    h = (Math.imul(h, 31) + 7) >>> 0;
  }
  return out;
}
/* 조사 처리: 받침 유무 */
function josa(word, a, b) {
  const c = word.charCodeAt(word.length - 1) - 0xAC00;
  if (c < 0 || c > 11171) return a;
  return (c % 28) ? a : b;
}
const eul = w => w + josa(w, '을', '를');
const wa = w => w + josa(w, '과', '와');
const eun = w => w + josa(w, '은', '는');
const ika = w => w + josa(w, '이', '가');
const euro = w => { const c = w.charCodeAt(w.length - 1) - 0xAC00; const j = (c < 0 || c > 11171) ? 0 : c % 28; return w + (j === 0 || j === 8 ? '로' : '으로'); };

