  c.chips = ['12가지 목적', lang.flagKo + ' ' + lang.nat, '화상·전화', '주 1~5회'];
  c.desc = `${lang.ko} 회화 과외 전국 매칭. 기초부터 비즈니스·시험·면접까지 12가지 목적별 커리큘럼. ${lang.exams.join(', ')} 대비 가능.`;
  const cr = [['홈', '/'], [lang.ko + '회화', null]];
  let body = heroBlock(c, cr);
