/* ── 전체 지역 인덱스 ───────────────────────────────────── */
function pageAllAreas(page) {
  const PER = 400, all = [];
  for (const s of SIDO) for (const g of gugunList(s[0]))
    for (const d of dongList(s[0], g.s)) all.push([s[2], g.ko, d, s[0], g.s]);
  const total = Math.ceil(all.length / PER), p = Math.min(Math.max(1, page), total);
  const slice = all.slice((p - 1) * PER, p * PER);
  const nums = []; for (let i = Math.max(1, p - 4); i <= Math.min(total, p + 4); i++) nums.push(i);
  const body = `<div class="hero"><div class="wrap">
${bc([['홈', '/'], ['전체 지역', null]])}
<h1>전체 지역 목록</h1>
<p class="sub">전국 ${all.length.toLocaleString()}개 읍면동에서 영어·중국어·일본어 회화 과외를 연결합니다. (${p}/${total} 페이지)</p>
</div></div>
<section><div class="wrap">
<div class="links">${slice.map(x =>
    `<a href="/english/area/${x[3]}/${x[4]}/${x[2].s}">${esc(x[0] + ' ' + x[1].split(' ').pop() + ' ' + x[2].ko)}</a>`).join('')}</div>
<div class="pager">
${p > 1 ? `<a href="/all-areas?page=${p - 1}">이전</a>` : ''}
${nums.map(n => n === p ? `<span>${n}</span>` : `<a href="/all-areas?page=${n}">${n}</a>`).join('')}
${p < total ? `<a href="/all-areas?page=${p + 1}">다음</a>` : ''}
</div></div></section>`;
  return layout({
    title: `전체 지역 목록 (${p}/${total}) | ${SITE.name}`,
    desc: `전국 ${all.length.toLocaleString()}개 읍면동 영어·중국어·일본어 회화 과외 지역 목록.`,
    kw: '지역별 회화 과외, 전국 영어회화, 동네 과외',
    path: '/all-areas' + (p > 1 ? '?page=' + p : ''), ogKey: 'home', body,
    ld: [ldBreadcrumb([['홈', '/'], ['전체 지역', '/all-areas']])]
  });
}

