/* ── SEO 엔드포인트 ─────────────────────────────────────── */
const INDEXNOW_KEY = 'ed8128cdf2e741588641135eb5a1a584';

function xmlUrl(loc, pri, freq) {
  return '<url><loc>' + SITE.origin + loc + '</loc><changefreq>' + (freq || 'weekly') +
    '</changefreq><priority>' + pri + '</priority></url>';
}

function sitemapIndex() {
  const maps = ['/sitemap-core.xml'];
  for (const l of LANGS) maps.push('/sitemap-dong-' + l.s + '.xml');
  for (const l of LANGS) for (const p of PURPOSES) maps.push('/sitemap-pd-' + l.s + '-' + p.s + '.xml');
  const now = new Date().toISOString();
  return '<?xml version="1.0" encoding="UTF-8"?>' +
    '<sitemapindex xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">' +
    maps.map(m => '<sitemap><loc>' + SITE.origin + m + '</loc><lastmod>' + now + '</lastmod></sitemap>').join('') +
    '</sitemapindex>';
}

function sitemapCore() {
  let u = xmlUrl('/', '1.0', 'daily') + xmlUrl('/list', '0.7') + xmlUrl('/about', '0.5') + xmlUrl('/contact', '0.8') + xmlUrl('/all-areas', '0.6');
  const totalPages = Math.ceil(dongCount() / 400);
  for (let i = 2; i <= totalPages; i++) u += xmlUrl('/all-areas?page=' + i, '0.3');
  for (const l of LANGS) {
    u += xmlUrl('/' + l.s, '0.95', 'daily');
    for (const p of PURPOSES) u += xmlUrl('/' + l.s + '/' + p.s, '0.9');
    for (const s of SIDO) {
      u += xmlUrl('/' + l.s + '/area/' + s[0], '0.8');
      for (const p of PURPOSES) u += xmlUrl('/' + l.s + '/' + p.s + '/' + s[0], '0.75');
      for (const g of gugunList(s[0])) {
        u += xmlUrl('/' + l.s + '/area/' + s[0] + '/' + g.s, '0.7');
        for (const p of PURPOSES) u += xmlUrl('/' + l.s + '/' + p.s + '/' + s[0] + '/' + g.s, '0.65');
      }
    }
  }
  return '<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">' + u + '</urlset>';
}

function sitemapDong(langSlug, purSlug) {
  let u = '';
  const base = purSlug ? '/' + langSlug + '/' + purSlug : '/' + langSlug + '/area';
  for (const s of SIDO) for (const g of gugunList(s[0])) for (const d of dongList(s[0], g.s))
    u += xmlUrl(base + '/' + s[0] + '/' + g.s + '/' + d.s, purSlug ? '0.55' : '0.6');
  return '<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">' + u + '</urlset>';
}

