function feedItems() {
  const out = [];
  for (const l of LANGS) {
    out.push(['[' + l.ko + '] ' + l.ko + ' 회화 과외', '/' + l.s,
      l.ko + ' 회화 과외 전국 매칭. ' + l.exams.join(', ') + ' 대비 가능.']);
    for (const p of PURPOSES)
      out.push(['[' + l.ko + '] ' + p.full, '/' + l.s + '/' + p.s,
        p.who + '을 위한 ' + l.ko + ' ' + p.full + ' 과정. ' + p.tag + '.']);
  }
  for (const s of SIDO)
    out.push([s[2] + ' 지역 회화 과외', '/english/area/' + s[0],
      s[1] + ' ' + gugunList(s[0]).length + '개 시군구 영어·중국어·일본어 회화 과외 안내.']);
  return out;
}

function atomXml() {
  const now = new Date().toISOString();
  const items = feedItems();
  return '<?xml version="1.0" encoding="UTF-8"?>' +
    '<feed xmlns="http://www.w3.org/2005/Atom" xml:lang="ko">' +
    '<title>' + esc(SITE.name) + '</title>' +
    '<subtitle>' + esc(SITE.desc) + '</subtitle>' +
    '<link rel="alternate" type="text/html" href="' + SITE.origin + '"/>' +
    '<link rel="self" type="application/atom+xml" href="' + SITE.origin + '/atom.xml"/>' +
    '<id>' + SITE.origin + '/</id>' +
    '<updated>' + now + '</updated>' +
    '<author><name>' + esc(SITE.name) + '</name><email>' + SITE.email + '</email></author>' +
    items.map(i => '<entry>' +
      '<title>' + esc(i[0]) + '</title>' +
      '<link rel="alternate" type="text/html" href="' + SITE.origin + i[1] + '"/>' +
      '<id>' + SITE.origin + i[1] + '</id>' +
      '<updated>' + now + '</updated>' +
      '<summary type="text">' + esc(i[2]) + '</summary>' +
      '</entry>').join('') +
    '</feed>';
}

function rssXml() {
  const items = feedItems();
  const now = new Date().toUTCString();
  return '<?xml version="1.0" encoding="UTF-8"?><rss version="2.0"><channel>' +
    '<title>' + SITE.name + '</title><link>' + SITE.origin + '</link>' +
    '<description>' + esc(SITE.desc) + '</description><language>ko</language><lastBuildDate>' + now + '</lastBuildDate>' +
    '<atom:link xmlns:atom="http://www.w3.org/2005/Atom" href="' + SITE.origin + '/rss.xml" rel="self" type="application/rss+xml"/>' +
    items.map(i => '<item><title>' + esc(i[0]) + '</title><link>' + SITE.origin + i[1] + '</link>' +
      '<guid>' + SITE.origin + i[1] + '</guid><description>' + esc(i[2]) + '</description>' +
      '<pubDate>' + now + '</pubDate></item>').join('') +
    '</channel></rss>';
}

/* ── 텔레그램 알림 ──────────────────────────────────────── */
const TG_LABEL = {
  tel: '전화 버튼 클릭', sms: '문자 버튼 클릭', form: '상담 버튼 클릭',
  cta: '상담 신청 버튼 클릭', contact: '상담 신청 접수'
};

/* 경로에서 지역·언어·목적 해석 */
function describePath(path) {
  const seg = String(path || '').split('?')[0].split('/').filter(Boolean);
  const out = { area: '', lang: '', pur: '', kind: '일반 페이지' };
  if (!seg.length) { out.kind = '메인'; return out; }
  const lang = LANG_BY[seg[0]];
  if (!lang) {
    if (seg[0] === 'contact') out.kind = '상담문의 페이지';
    else if (seg[0] === 'about') out.kind = '소개 페이지';
    else if (seg[0] === 'all-areas') out.kind = '전체 지역 목록';
    return out;
  }
  out.lang = lang.ko;
  let rest;
  if (seg[1] === 'area') rest = seg.slice(2);
  else if (PUR_BY[seg[1]]) { out.pur = PUR_BY[seg[1]].ko; rest = seg.slice(2); }
  else { out.kind = lang.ko + ' 허브'; return out; }
  const names = [];
  const sido = rest[0] ? SIDO_BY[rest[0]] : null;
  if (sido) {
    names.push(sido.short);
    const gugun = rest[1] && !rest[1].startsWith('group-') ? findGugun(sido.s, rest[1]) : null;
    if (gugun) {
      names.push(gugun.ko.split(' ').pop());
      const dong = rest[2] ? findDong(sido.s, gugun.s, rest[2]) : null;
      if (dong) names.push(dong.ko);
    }
  }
  out.area = names.join(' ');
  out.kind = out.area ? '지역 페이지' : (out.pur ? '목적 페이지' : '언어 페이지');
  if (out.area) {
    out.area = out.area + ' ' + lang.ko + ' 회화 과외' + (out.pur ? ' · ' + out.pur : '');
    out.lang = '';
    out.pur = '';
  }
  return out;
}

function refName(ref) {
  if (!ref) return '직접 방문 또는 알 수 없음';
  try {
    const h = new URL(ref).hostname.replace(/^www\./, '');
    if (h === SITE.domain) return '사이트 내부 이동';
    if (h.includes('naver')) return '네이버';
    if (h.includes('google')) return '구글';
    if (h.includes('daum')) return '다음';
    if (h.includes('bing')) return 'Bing';
    if (h.includes('kakao')) return '카카오';
    if (h.includes('instagram')) return '인스타그램';
    if (h.includes('facebook')) return '페이스북';
    if (h.includes('youtube')) return '유튜브';
    return h;
  } catch (e) { return '알 수 없음' }
}

function kstNow() {
  const d = new Date(Date.now() + 9 * 3600000);
  const p = n => String(n).padStart(2, '0');
  return d.getUTCFullYear() + '-' + p(d.getUTCMonth() + 1) + '-' + p(d.getUTCDate()) +
    ' ' + p(d.getUTCHours()) + ':' + p(d.getUTCMinutes());
}

async function notifyTelegram(env, event, path, req) {
  const TG_TOKEN = env && env.TG_TOKEN;
  const TG_CHAT = env && env.TG_CHAT;
  if (!TG_TOKEN || !TG_CHAT) return;
  const label = TG_LABEL[event];
  if (!label) return;
  const d = describePath(path);
  const ua = req.headers.get('user-agent') || '';
  const mobile = /Mobile|Android|iPhone|iPad/i.test(ua) ? '모바일' : 'PC';
  const langPart = d.lang ? d.lang + (d.pur ? ' · ' + d.pur : '') : '';
  let ko;
  if (d.area) ko = [d.area, langPart].filter(Boolean).join(' · ');
  else if (langPart) ko = d.kind + ' · ' + langPart;
  else ko = d.kind;
  const lines = [];
  lines.push((event === 'tel' ? '📞 ' : '📝 ') + label);
  lines.push('');
  lines.push('사이트: ' + SITE.name + ' (' + SITE.domain + ')');
  lines.push('페이지: ' + SITE.origin + path);
  lines.push('검색 키워드: ' + ko);
  lines.push('유입: ' + refName(req.headers.get('referer')));
  lines.push('기기: ' + mobile);
  lines.push('시각: ' + kstNow() + ' (KST)');
  try {
    await fetch('https://api.telegram.org/bot' + TG_TOKEN + '/sendMessage', {
      method: 'POST', headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        chat_id: TG_CHAT, text: lines.join('\n'), disable_web_page_preview: true
      })
    });
  } catch (e) { /* 알림 실패는 무시 */ }
}

/* ── 봇 필터 ────────────────────────────────────────────── */
const BOT_RE = /bot|crawl|spider|slurp|bingpreview|facebookexternalhit|whatsapp|telegram|curl|wget|python|axios|headless|lighthouse|pagespeed|gptbot|claude|perplexity|yeti|daumoa|cs\.daum\.net|compatible;\s*daum\/|semrush|ahrefs|mj12|dotbot|petal|bytespider|applebot|amazonbot|monitor|uptime|scan/i;
/* 통합 대시보드(allcarestudy)의 events 테이블에 기록 — site 키: globaltalkup */
const TRACK_SITE = 'globaltalkup';
/* 이 사이트 고유 이벤트명 → 대시보드 공통 타입 */
const TRACK_TYPE = { view: 'view', tel: 'tel', sms: 'sms', form: 'contact', cta: 'contact', contact: 'contact' };

async function handleTrack(req, env, ctx) {
  try {
    const body = await req.json();
    const ua = req.headers.get('user-agent') || '';
    if (body.e === 'view' && (BOT_RE.test(ua) || skipViewCf(req, req.headers.get('CF-Connecting-IP') || ''))) return new Response('{"ok":true}', { headers: { 'content-type': 'application/json' } });
    if (TG_LABEL[body.e] && !BOT_RE.test(ua)) {
      const p = notifyTelegram(env, body.e, String(body.p || '/').slice(0, 300), req);
      if (ctx && ctx.waitUntil) ctx.waitUntil(p); else await p;
    }
    const ty = TRACK_TYPE[body.e];
    if (env && env.DB && ty) {
      await env.DB.prepare('INSERT INTO events (site,type,page,ref,ip,ts,ua,device,source,keyword) VALUES (?,?,?,?,?,?,?,?,?,?)')
        .bind(TRACK_SITE, ty, String(body.p || '').slice(0, 300),
          (req.headers.get('referer') || '').slice(0, 120),
          req.headers.get('CF-Connecting-IP') || '', new Date().toISOString(),
          ...tkMeta(ua, req.headers.get('referer') || '', 'globaltalkup.com')).run();
    }
  } catch (e) { /* 추적 실패는 무시 */ }
  return new Response('{"ok":true}', { headers: { 'content-type': 'application/json' } });
}

/* ── 상담문의 (GAS 연동 · 절대 수정 금지) ─────────────────── */
const CORS = { 'content-type': 'application/json', 'access-control-allow-origin': '*',
  'access-control-allow-methods': 'POST,OPTIONS', 'access-control-allow-headers': 'Content-Type' };

async function handleContact(req) {
  if (req.method === 'OPTIONS') return new Response(null, { headers: CORS });
  try {
    const data = await req.json();
    const payload = {
      name: data.name || '', phone: data.phone || '', grade: data.grade || '',
      subject: data.subject || '', address: data.address || '',
      message: data.message || '', page: data.page || '', type: 'globaltalkup'
    };
    const res = await fetch(GAS_URL, {
      method: 'POST', headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(payload), redirect: 'follow'
    });
    const text = await res.text();
    let out; try { out = JSON.parse(text); } catch (e) { out = { ok: false, error: text }; }
    return new Response(JSON.stringify(out.ok ? { ok: true } : { ok: false, error: out.error || 'gas' }), { headers: CORS });
  } catch (e) {
    return new Response(JSON.stringify({ ok: false, error: e.message }), { headers: CORS });
  }
}

/* ── 응답 헬퍼 ──────────────────────────────────────────── */
const H_HTML = { 'content-type': 'text/html;charset=utf-8', 'cache-control': 'public,max-age=3600,s-maxage=86400' };
const H_XML = { 'content-type': 'application/xml;charset=utf-8', 'cache-control': 'public,max-age=3600' };
const H_TXT = { 'content-type': 'text/plain;charset=utf-8', 'cache-control': 'public,max-age=3600' };
const html = (s, st) => new Response(s, { status: st || 200, headers: H_HTML });
const xml = s => new Response(s, { headers: H_XML });
const txt = s => new Response(s, { headers: H_TXT });
const redir = loc => new Response(null, { status: 301, headers: { location: loc } });

/* ── 라우터 ─────────────────────────────────────────────── */
async function route(req, env, ctx) {
  const url = new URL(req.url);
  let path = url.pathname.replace(/\/+$/, '') || '/';

  /* 대문자 경로는 소문자로 301 (중복 색인 방지) */
  if (/[A-Z]/.test(path) && !path.startsWith('/og/')) {
    return redir(path.toLowerCase() + url.search);
  }

  if (path === '/api/contact') return handleContact(req);
  if (path === '/api/track') return handleTrack(req, env, ctx);

  if (path === '/robots.txt') return txt(robotsTxt());
  if (path === '/llms.txt') return txt(llmsTxt());
  if (path === '/llms-full.txt') return txt(llmsFullTxt());
  if (path === '/rss.xml') return xml(rssXml());
  if (path === '/atom.xml') return new Response(atomXml(), { headers: { 'content-type': 'application/atom+xml;charset=utf-8', 'cache-control': 'public,max-age=3600' } });
  if (path === '/sitemap.xml') return xml(sitemapIndex());
  if (path === '/sitemap-core.xml') return xml(sitemapCore());
  if (path === '/' + INDEXNOW_KEY + '.txt') return txt(INDEXNOW_KEY);
  if(path==="/og.svg") return new Response(`<svg xmlns="http://www.w3.org/2000/svg" width="1200" height="630" viewBox="0 0 1200 630"><defs><linearGradient id="g" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="#0F172A"/><stop offset="1" stop-color="#1E5EFF"/></linearGradient></defs><rect width="1200" height="630" fill="url(#g)"/><rect x="60" y="60" width="1080" height="510" rx="28" fill="none" stroke="rgba(255,255,255,.28)" stroke-width="2"/><text x="600" y="300" text-anchor="middle" font-family="Pretendard,'Apple SD Gothic Neo','Malgun Gothic',sans-serif" font-size="86" font-weight="800" fill="#ffffff">글로벌톡업</text><text x="600" y="378" text-anchor="middle" font-family="Pretendard,'Apple SD Gothic Neo','Malgun Gothic',sans-serif" font-size="34" font-weight="500" fill="rgba(255,255,255,.88)">영어·중국어·일본어 화상 회화 과외</text><text x="600" y="530" text-anchor="middle" font-family="Pretendard,'Apple SD Gothic Neo','Malgun Gothic',sans-serif" font-size="28" font-weight="600" fill="rgba(255,255,255,.72)">globaltalkup.com</text></svg>`,{headers:{"content-type":"image/svg+xml; charset=UTF-8","cache-control":"public, max-age=86400"}});
  if (path === '/favicon.ico') return new Response(b64bin(FAV_B64), { headers: { 'content-type': 'image/x-icon', 'cache-control': 'public,max-age=2592000' } });
  if (path === '/icon-192.png') return new Response(b64bin(ICON192_B64), { headers: { 'content-type': 'image/png', 'cache-control': 'public,max-age=2592000,immutable' } });
  if (path === '/manifest.json') return new Response(manifestJson(), { headers: { 'content-type': 'application/manifest+json;charset=utf-8', 'cache-control': 'public,max-age=86400' } });

  let m = path.match(/^\/sitemap-dong-([a-z]+)\.xml$/);
  if (m && LANG_BY[m[1]]) return xml(sitemapDong(m[1], null));
  m = path.match(/^\/sitemap-pd-([a-z]+)-([a-z]+)\.xml$/);
  if (m && LANG_BY[m[1]] && PUR_BY[m[2]]) return xml(sitemapDong(m[1], m[2]));

  const ogm = path.match(/^\/og\/([a-z0-9-]+)\.png$/);
  if (ogm) return new Response(b64bin(ogImage(ogm[1])), {
    headers: { 'content-type': 'image/png', 'cache-control': 'public,max-age=2592000,immutable' } });

  if (path === '/') return html(pageHome());
  if (path === '/about') return html(pageAbout());
  if (path === '/contact') return html(pageContact());
  if (path === '/list') return html(pageList());
  if (path === '/all-areas') return html(pageAllAreas(parseInt(url.searchParams.get('page') || '1', 10) || 1));

  const seg = path.split('/').filter(Boolean);
  const lang = LANG_BY[seg[0]];
  if (!lang) return html(page404(), 404);
  if (seg.length === 1) return html(pageLang(lang));

  /* /{lang}/area/... 또는 /{lang}/{purpose}/... */
  let pur = null, rest;
  if (seg[1] === 'area') { rest = seg.slice(2); }
  else if (PUR_BY[seg[1]]) { pur = PUR_BY[seg[1]]; rest = seg.slice(2); }
  else return html(page404(), 404);

  if (rest.length === 0) return html(pageArea(lang, pur, null, null, null, path));

  const sido = SIDO_BY[rest[0]];
  if (!sido) return html(page404(), 404);
  if (rest.length === 1) return html(pageArea(lang, pur, sido, null, null, path));

  /* 권역 페이지 */
  if (rest[1].startsWith('group-')) {
    const gname = rest[1].slice(6);
    const grp = (AREA_GROUPS[sido.s] || []).find(g => g.s === gname);
    if (!grp) return html(page404(), 404);
    return html(pageGroup(lang, pur, sido, grp, path));
  }

  const gugun = findGugun(sido.s, rest[1]);
  if (!gugun) return html(page404(), 404);
  if (rest.length === 2) return html(pageArea(lang, pur, sido, gugun, null, path));

  const dong = findDong(sido.s, gugun.s, rest[2]);
  if (!dong) return html(page404(), 404);
  if (rest.length === 3) return html(pageArea(lang, pur, sido, gugun, dong, path));

  return html(page404(), 404);
}

/* ── IndexNow (Cron) ────────────────────────────────────── */
async function indexNowPush(hour) {
  const all = [];
  for (const l of LANGS) {
    all.push(SITE.origin + '/' + l.s);
    for (const p of PURPOSES) all.push(SITE.origin + '/' + l.s + '/' + p.s);
  }
  for (const s of SIDO) for (const g of gugunList(s[0])) for (const d of dongList(s[0], g.s))
    for (const l of LANGS) all.push(SITE.origin + '/' + l.s + '/area/' + s[0] + '/' + g.s + '/' + d.s);
  const SIZE = 9000;
  const chunks = Math.ceil(all.length / SIZE);
  const idx = hour % chunks;
  const urlList = all.slice(idx * SIZE, (idx + 1) * SIZE);
  const body = JSON.stringify({ host: SITE.domain, key: INDEXNOW_KEY,
    keyLocation: SITE.origin + '/' + INDEXNOW_KEY + '.txt', urlList });
  const opt = { method: 'POST', headers: { 'Content-Type': 'application/json' }, body };
  await Promise.all([
    indexnowFetch(opt).catch(() => null),
    fetch('https://searchadvisor.naver.com/indexnow', opt).catch(() => null)
  ]);
}

export default {
  async fetch(req, env, ctx) {
    try { return await route(req, env, ctx); }
    catch (e) { return new Response('Error: ' + e.message, { status: 500 }); }
  },
  async scheduled(event, env, ctx) {
    const hour = Math.floor(Date.now() / 3600000);
    ctx.waitUntil(indexNowPush(hour));
  }
};
